// ValidateAndBuild validates the instruction parameters and accounts;
// if there is a validation error, it returns the error.
// Otherwise, it builds and returns the instruction.
func (inst CreateV2Instruction) ValidateAndBuild() (*Instruction, error) {
	if err := inst.Validate(); err != nil {
		return nil, err
	}
	return inst.Build(), nil
}

func (inst *CreateV2Instruction) Validate() error {
	// Check whether all (required) parameters are set:
	{
		if inst.Name == nil {
			return errors.New("Name parameter is not set")
		}
		if inst.Symbol == nil {
			return errors.New("Symbol parameter is not set")
		}
		if inst.Uri == nil {
			return errors.New("Uri parameter is not set")
		}
		if inst.Creator == nil {
			return errors.New("Creator parameter is not set")
		}
		if inst.IsMayhemMode == nil {
			return errors.New("IsMayhemMode parameter is not set")
		}
	}

	// Check whether all (required) accounts are set:
	{
		if inst.AccountMetaSlice[0] == nil {
			return errors.New("accounts.Mint is not set")
		}
		if inst.AccountMetaSlice[1] == nil {
			return errors.New("accounts.MintAuthority is not set")
		}
		if inst.AccountMetaSlice[2] == nil {
			return errors.New("accounts.BondingCurve is not set")
		}
		if inst.AccountMetaSlice[3] == nil {
			return errors.New("accounts.AssociatedBondingCurve is not set")
		}
		if inst.AccountMetaSlice[4] == nil {
			return errors.New("accounts.Global is not set")
		}
		if inst.AccountMetaSlice[5] == nil {
			return errors.New("accounts.User is not set")
		}
		if inst.AccountMetaSlice[6] == nil {
			return errors.New("accounts.SystemProgram is not set")
		}
		if inst.AccountMetaSlice[7] == nil {
			return errors.New("accounts.TokenProgram is not set")
		}
		if inst.AccountMetaSlice[8] == nil {
			return errors.New("accounts.AssociatedTokenProgram is not set")
		}
		if inst.AccountMetaSlice[9] == nil {
			return errors.New("accounts.MayhemProgramId is not set")
		}
		if inst.AccountMetaSlice[10] == nil {
			return errors.New("accounts.GlobalParams is not set")
		}
		if inst.AccountMetaSlice[11] == nil {
			return errors.New("accounts.SolVault is not set")
		}
		if inst.AccountMetaSlice[12] == nil {
			return errors.New("accounts.MayhemState is not set")
		}
		if inst.AccountMetaSlice[13] == nil {
			return errors.New("accounts.MayhemTokenVault is not set")
		}
		if inst.AccountMetaSlice[14] == nil {
			return errors.New("accounts.EventAuthority is not set")
		}
		if inst.AccountMetaSlice[15] == nil {
			return errors.New("accounts.Program is not set")
		}
	}
	return nil
}

func (inst *CreateV2Instruction) EncodeToTree(parent ag_treeout.Branches) {
	parent.Child(ag_format.Program(ProgramName, ProgramID)).
		//
		ParentFunc(func(programBranch ag_treeout.Branches) {
			programBranch.Child(ag_format.Instruction("CreateV2")).
				//
				ParentFunc(func(instructionBranch ag_treeout.Branches) {

					// Parameters of the instruction:
					instructionBranch.Child("Params[len=5]").ParentFunc(func(paramsBranch ag_treeout.Branches) {
						paramsBranch.Child(ag_format.Param("          Name", *inst.Name))
						paramsBranch.Child(ag_format.Param("        Symbol", *inst.Symbol))
						paramsBranch.Child(ag_format.Param("           Uri", *inst.Uri))
						paramsBranch.Child(ag_format.Param("       Creator", *inst.Creator))
						paramsBranch.Child(ag_format.Param("  IsMayhemMode", *inst.IsMayhemMode))
					})

					// Accounts of the instruction:
					instructionBranch.Child("Accounts[len=16]").ParentFunc(func(accountsBranch ag_treeout.Branches) {
						accountsBranch.Child(ag_format.Meta("                    mint", inst.AccountMetaSlice.Get(0)))
						accountsBranch.Child(ag_format.Meta("          mint_authority", inst.AccountMetaSlice.Get(1)))
						accountsBranch.Child(ag_format.Meta("           bonding_curve", inst.AccountMetaSlice.Get(2)))
						accountsBranch.Child(ag_format.Meta("associated_bonding_curve", inst.AccountMetaSlice.Get(3)))
						accountsBranch.Child(ag_format.Meta("                  global", inst.AccountMetaSlice.Get(4)))
						accountsBranch.Child(ag_format.Meta("                    user", inst.AccountMetaSlice.Get(5)))
						accountsBranch.Child(ag_format.Meta("          system_program", inst.AccountMetaSlice.Get(6)))
						accountsBranch.Child(ag_format.Meta("           token_program", inst.AccountMetaSlice.Get(7)))
						accountsBranch.Child(ag_format.Meta("associated_token_program", inst.AccountMetaSlice.Get(8)))
						accountsBranch.Child(ag_format.Meta("       mayhem_program_id", inst.AccountMetaSlice.Get(9)))
						accountsBranch.Child(ag_format.Meta("           global_params", inst.AccountMetaSlice.Get(10)))
						accountsBranch.Child(ag_format.Meta("               sol_vault", inst.AccountMetaSlice.Get(11)))
						accountsBranch.Child(ag_format.Meta("            mayhem_state", inst.AccountMetaSlice.Get(12)))
						accountsBranch.Child(ag_format.Meta("      mayhem_token_vault", inst.AccountMetaSlice.Get(13)))
						accountsBranch.Child(ag_format.Meta("         event_authority", inst.AccountMetaSlice.Get(14)))
						accountsBranch.Child(ag_format.Meta("                 program", inst.AccountMetaSlice.Get(15)))
					})
				})
		})
}

